# Inspect song details for each recommended song; filter R&B and release year
from datetime import datetime

def parse_year(dt_str):
    if not dt_str:
        return None
    # expected like '2019-01-01T00:00:00'
    try:
        return datetime.fromisoformat(dt_str).year
    except Exception:
        try:
            return int(str(dt_str)[:4])
        except Exception:
            return None

# recommendations and this_year/last_year should exist from prior steps
print('have recommendations', 'recommendations' in globals(), 'count', len(recommendations))

song_details = []
for idx, r in enumerate(recommendations):
    sid = r['song_id']
    s = apis.spotify.show_song(song_id=sid)
    song_details.append({
        'song_id': sid,
        'title': r.get('title') or s.get('title'),
        'album_title': r.get('album_title') or s.get('album_title'),
        'genre': s.get('genre'),
        'release_date': s.get('release_date'),
